<dialog id="recipe-{{ $item->id??'new' }}" class="editor-dialog"><div class="dialog-heading"><h2>{{ $item?'Edit recipe':'A fresh page in the notebook' }}</h2><button data-close aria-label="Close recipe editor">×</button></div><form action="/admin/recipes{{ $item?'/'.$item->id:'' }}" method="post" enctype="multipart/form-data" class="dialog-content">@csrf<div class="form-grid">@foreach(['title'=>'Recipe title','category'=>'Category','minutes'=>'Cooking time in minutes','servings'=>'Servings'] as $key=>$label)<label>{{ $label }}<input name="{{ $key }}" value="{{ $item->$key??'' }}" type="{{ in_array($key,['minutes','servings'])?'number':'text' }}" @if(in_array($key,['minutes','servings'])) min="1" @endif required></label>@endforeach @foreach(['description'=>'Introduction','ingredients'=>'Ingredients one per line','steps'=>'Method one step per line'] as $key=>$label)<label class="full">{{ $label }}<textarea name="{{ $key }}" rows="{{ $key==='description'?3:6 }}" required>{{ $item->$key??'' }}</textarea></label>@endforeach<label class="full">Recipe image<input type="file" name="image" accept="image/png,image/jpeg,image/webp"><small>JPG, PNG or WebP. Up to 2 MB.</small></label><label class="checkbox full"><input type="checkbox" name="active" value="1" @checked($item->active??true)> Published on website</label></div><button class="button button-blue">Save recipe</button></form>@if($item&&$item->active)<form action="/admin/archive/recipes/{{ $item->id }}" method="post" class="dialog-archive">@csrf<button class="text-link" data-confirm="Archive this recipe?">Archive recipe</button></form>@endif</dialog>
